import calendar
from datetime import date, timedelta

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    if freq == "WEEKLY":
        target_days = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while len(result) < count:
            week_monday = week0_monday + timedelta(days=step * k * 7)
            for wd in target_days:
                candidate = week_monday + timedelta(days=wd)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        break
            step += 1
        return result

    if freq == "MONTHLY":
        m0 = start_date.year * 12 + (start_date.month - 1)
        step = 0
        if len(parts) == 3:
            d = int(parts[2])
            while len(result) < count:
                year, month0 = divmod(m0 + step * k, 12)
                month = month0 + 1
                _, days_in_month = calendar.monthrange(year, month)
                day = days_in_month if d == -1 else d
                if day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                step += 1
        else:
            n = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(result) < count:
                year, month0 = divmod(m0 + step * k, 12)
                month = month0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                first_day = 1 + (target_wd - first_wd) % 7
                if n == -1:
                    day = first_day + ((days_in_month - first_day) // 7) * 7
                else:
                    day = first_day + (n - 1) * 7
                if day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                step += 1
        return result

    if freq == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        step = 0
        while len(result) < count:
            year = start_date.year + step * k
            try:
                candidate = date(year, mm, dd)
            except ValueError:
                candidate = None
            if candidate is not None and candidate >= start_date:
                result.append(candidate.isoformat())
            step += 1
        return result

    raise ValueError(f"Unsupported rule: {rule}")
